import os
import re
import time
from moler.device import DeviceFactory
from taf.rfrl.bts.devices.du.logs_collecting.bip_collector import start_bip_trace_log_capturing, \
    stop_bip_trace_log_capturing, download_bip_logs
from taf.rfrl.utilities import test_config
from taf.rfrl.utilities.tl_config import is_testline_of_cloud_type
from taf.rfrl.bts.devices.cu.cu_logs_collector import CuLogsCollector


def start_collecting_logs_during_attach():
    """
    Start collecting logs before attach
    """
    start_bip_trace_log_capturing(timeout=40)


def stop_collecting_logs_after_attach():
    """
    Stop collecting logs after attach finished.
    """
    stop_bip_trace_log_capturing()


def download_logs_from_gnb(sub_dir='data_transfer', clear_source_dir=True, is_traffic_multi_radio_bearer=False):
    """
    Download logs from gNB to ${LOG_PATH} directory on local VM.
    :param sub_dir:
    :param clear_source_dir: clear source dir if exists
    :param is_traffic_multi_radio_bearer: boolean - indicates multi radio bearer traffic
    """
    log_path = test_config.set_test_case_log_path()
    download_dir = os.path.join(log_path, sub_dir)
    if clear_source_dir and os.path.exists(download_dir):
        unix = DeviceFactory.get_device('UnixLocal')
        rm = unix.get_cmd(cmd_name="rm",
                          cmd_params={"file": os.path.join(re.escape(download_dir), '*'),
                                      "options": '-rf'})
        rm()
    if sub_dir == 'data_transfer' and is_traffic_multi_radio_bearer and is_testline_of_cloud_type():
        CuLogsCollector().download_bip_logs_from_upue_interface(log_dir=download_dir)
    else:
        download_bip_logs(download_dir=download_dir)


def collect_logs_during_data_transfer(direction='DL', is_traffic_multi_radio_bearer=False):
    """
    Collect logs during data transfer.
    :param direction: DL or UL
    :param is_traffic_multi_radio_bearer: boolean - indicates multi radio bearer traffic
    """
    if is_traffic_multi_radio_bearer:
        if is_testline_of_cloud_type():
            CuLogsCollector().start_tcpdump_collection_on_backhaul_upue_interface(
                capture_file='tcpdump_L2L1_s1uplane.pcap',
                count=50,
                background=True)
            time.sleep(2)
            CuLogsCollector().stop_tcpdump_collection_on_upue_interfacel()
        else:
            _start_collecting_logs_during_data_transfer(direction=direction,
                                                        mirroring_script_params={'backhaul_mirroring': 'true',
                                                                                 'l2_l1_bip': 'false',
                                                                                 'number_of_files': 1,
                                                                                 'file_size_mbytes': 2})
            time.sleep(4)
            _stop_collecting_logs_during_data_transfer()
    else:
        _start_collecting_logs_during_data_transfer(direction=direction,
                                                    mirroring_script_params={'number_of_files': 1,
                                                                             'file_size_mbytes': 1}
                                                    )
        time.sleep(4)
        _stop_collecting_logs_during_data_transfer()


def _start_collecting_logs_during_data_transfer(direction, mirroring_script_params={}):
    # bip_filters = BipFilterGenerator.get_filters(direction=direction)
    # mirroring_script_params = {'filter': bip_filters, 'filtering': 'on'}
    start_bip_trace_log_capturing(mirroring_script_params=mirroring_script_params)


def _stop_collecting_logs_during_data_transfer():
    # stop_collecting_tti_trace()
    stop_bip_trace_log_capturing()


class BipFilterGenerator(object):
    bip_filters = {
        'PuschReceiveReq': {'value': r'ether[0x18:2]==0x249', 'direction': 'UL'},
        'PuschReceiveRespLo': {'value': r'ether[0x18:2]==0x23a', 'direction': 'UL'},
        'PdschSendReq': {'value': r'ether[0x18:2]==0x130', 'direction': 'DL'},
        'PdschPayloadTbSendReq': {'value': r'ether[0x18:2]==0x108', 'direction': 'DL'},
        'PucchReceiveReq': {'value': r'ether[0x18:2]==0x24c', 'direction': 'DL'},
        'PucchReceiveRespHarqD': {'value': r'ether[0x18:2]==0x24d', 'direction': 'DL'},
        'PdcchSendReq': {'value': r'ether[0x18:2]==0x133', 'direction': 'BOTH'},
    }

    @staticmethod
    def get_filters(direction):
        filters = []
        if direction == 'BOTH':
            filters = [record['value'] for record in BipFilterGenerator.bip_filters.values()]
        else:
            for record in BipFilterGenerator.bip_filters.values():
                if record['direction'] in ['BOTH', direction]:
                    filters.append(record['value'])

        return " || ".join(filters)
